/**
 * Custom Worker entry (PHASE-4-FOUNDATION §3 "Sweep").
 *
 * Wraps the OpenNext fetch handler and adds `scheduled()` for the every-minute Cron Trigger.
 * The cron calls the same sweep as `POST /api/cron/sweep`, by sending that route an internal
 * request with the `CRON_SECRET` bearer. One code path, and OpenNext sets up `process.env`
 * and the request context exactly as for a normal request.
 */

// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`; it may not exist when type-checking.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as openNextHandler } from "./.open-next/worker.js";

// Durable Objects that OpenNext may use for caching; re-exported so bindings can reference them.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

const SWEEP_URL = "https://cron.internal/api/cron/sweep";

export default {
  fetch: openNextHandler.fetch,

  async scheduled(controller, env, ctx) {
    if (!env.CRON_SECRET) {
      console.error(JSON.stringify({ level: "error", msg: "cron: CRON_SECRET is not set; sweep skipped" }));
      return;
    }
    const request = new Request(SWEEP_URL, {
      method: "POST",
      headers: {
        authorization: `Bearer ${env.CRON_SECRET}`,
        "x-cron-scheduled-time": new Date(controller.scheduledTime).toISOString(),
      },
    });
    const response: Response = await openNextHandler.fetch(request, env, ctx);
    if (!response.ok) {
      // Throwing marks the invocation as failed in Cloudflare's cron logs.
      throw new Error(`cron: sweep returned ${response.status}`);
    }
  },
} satisfies ExportedHandler<Env>;
